function checkGroup(name,label,options,selected){let values=Array.isArray(selected)?selected:String(selected||'').split('|').filter(Boolean);return '<fieldset class="wide choiceGroup"><legend>'+label+'</legend>'+options.map(o=>'<label class="choice"><input type="checkbox" name="'+name+'" value="'+esc(o)+'"'+(values.includes(o)?' checked':'')+'> '+esc(o)+'</label>').join('')+'</fieldset>'}
function radioGroup(name,label,options,value){return '<fieldset class="wide choiceGroup"><legend>'+label+'</legend>'+options.map(o=>'<label class="choice"><input type="radio" name="'+name+'" value="'+esc(o)+'"'+(value===o?' checked':'')+'> '+esc(o)+'</label>').join('')+'</fieldset>'}
function exactInput(name,label,type='text'){let value=current[name]??'';return '<label class="'+(type==='textarea'?'wide':'')+'">'+label+(type==='textarea'?'<textarea name="'+name+'">'+esc(value)+'</textarea>':'<input type="'+type+'" name="'+name+'" value="'+esc(value)+'">')+'</label>'}
let evidenceDrafts={pictures:[],attendanceFile:[]},currentBase=null;
function evidenceList(value){if(Array.isArray(value))return value.filter(Boolean);return value&&typeof value==='object'?[value]:[]}
function previewMarkup(name,file,url,isSaved=false,index=0){if(!file)return '';let type=file.type||'',fileName=file.name||'Uploaded file',visual=type.startsWith('image/')?'<img src="'+esc(url)+'" alt="Preview of '+esc(fileName)+'">':type==='application/pdf'?'<iframe src="'+esc(url)+'" title="Preview of '+esc(fileName)+'"></iframe>':'<div style="padding:28px;text-align:center;color:var(--muted);font-weight:750">Preview is not available for this file type.</div>';return '<div class="filePreview" data-preview="'+name+'">'+visual+'<div class="fileMeta"><a href="'+esc(url)+'" target="_blank" rel="noopener">'+esc(fileName)+'</a><span>'+formatBytes(file.size)+'</span><button type="button" class="deleteFile" data-delete-file="'+name+'" data-file-index="'+index+'" data-saved="'+(isSaved?'1':'0')+'">Delete file</button></div></div>'}
function formatBytes(size){if(!Number(size))return '';if(size<1024)return size+' B';if(size<1024*1024)return (size/1024).toFixed(1)+' KB';return (size/1024/1024).toFixed(1)+' MB'}
function uploadField(name,label,help){let existing=evidenceList(current[name]).map((f,i)=>previewMarkup(name,f,f.url,true,i)).join('');return '<div class="wide uploadField"><b>'+label+'</b><small>'+help+' You can select several files at once or add more later.</small><input type="file" name="'+name+'" multiple accept=".pdf,.xlsx,.xls,.csv,.png,.jpg,.jpeg"><div class="evidencePreviews" data-evidence-previews="'+name+'">'+existing+'</div></div>'}
function renderEvidencePreviews(kind){let box=document.querySelector('[data-evidence-previews="'+kind+'"]');if(!box)return;let saved=evidenceList(current[kind]),draft=evidenceDrafts[kind]||[];box.innerHTML=saved.map((f,i)=>previewMarkup(kind,f,f.url,true,i)).join('')+draft.map((f,i)=>previewMarkup(kind,f,URL.createObjectURL(f),false,i)).join('');wireDeleteButtons()}
function wireUploadPreviews(){evidenceDrafts={pictures:[],attendanceFile:[]};document.querySelectorAll('.uploadField input[type=file]').forEach(input=>input.onchange=()=>{evidenceDrafts[input.name].push(...input.files);input.value='';renderEvidencePreviews(input.name)});wireDeleteButtons()}
function wireDeleteButtons(){document.querySelectorAll('[data-delete-file]').forEach(button=>button.onclick=async()=>{let kind=button.dataset.deleteFile,index=Number(button.dataset.fileIndex);if(button.dataset.saved!=='1'){evidenceDrafts[kind].splice(index,1);renderEvidencePreviews(kind);return}if(!confirm('Delete this uploaded file?'))return;button.disabled=true;button.textContent='Deleting…';try{let files=evidenceList(current[kind]),f=files[index];files.splice(index,1);current[kind]=files;let saved=await persistSnapshot(current,currentBase);if(f?.key){let r=await fetch('/api/files?key='+encodeURIComponent(f.key),{method:'DELETE'});if(!r.ok)throw new Error('The record was saved, but the stored file could not be removed.')}events=events.map(x=>x.id===saved.id?saved:x);current=structuredClone(saved);currentBase=structuredClone(saved);renderEvidencePreviews(kind);render()}catch(err){button.disabled=false;button.textContent='Delete file';alert(err.message||'The file could not be deleted.')}})}
const saveQueues=new Map();
function saveButtonState(state,message){let button=$('#eventForm .save');if(!button)return;button.classList.remove('saving','saved','saveError');if(state)button.classList.add(state);button.textContent=message}
async function fetchWithTimeout(url,options,timeout=12000){let controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{return await fetch(url,{...options,signal:controller.signal})}finally{clearTimeout(timer)}}
async function persistSnapshot(snapshot,base){let lastError;for(let attempt=0;attempt<2;attempt++){try{let r=await fetchWithTimeout('/api/events',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({event:snapshot,base:base||events.find(item=>item.id===snapshot.id)||null})});if(!r.ok){let detail=await r.json().catch(()=>({}));throw new Error(detail.error||'Record save failed')}return (await r.json()).event}catch(error){lastError=error;if(attempt===0)await new Promise(resolve=>setTimeout(resolve,250))}}throw lastError}
function queueEventSave(snapshot){let id=snapshot.id,state=saveQueues.get(id)||{running:false,pending:null,waiters:[]};state.pending=structuredClone(snapshot);saveQueues.set(id,state);let promise=new Promise((resolve,reject)=>state.waiters.push({resolve,reject}));if(!state.running){state.running=true;(async()=>{try{while(state.pending){let next=state.pending;state.pending=null;let saved=await persistSnapshot(next);if(!state.pending){events=events.map(x=>x.id===id?saved:x);if(current?.id===id)Object.assign(current,saved)}}let waiters=state.waiters.splice(0);waiters.forEach(w=>w.resolve(events.find(e=>e.id===id)))}catch(error){state.pending=null;let waiters=state.waiters.splice(0);waiters.forEach(w=>w.reject(error))}finally{state.running=false;if(state.pending)queueEventSave(state.pending)}})()}return promise}
