async function uploadEvidenceFiles(files,kind){let uploaded=[];for(let file of files){if(file.size>20*1024*1024)throw new Error('Each file must be 20 MB or smaller.');let r=await fetch('/api/files/'+encodeURIComponent(current.id)+'/'+kind,{method:'PUT',headers:{'content-type':file.type||'application/octet-stream','x-file-name':encodeURIComponent(file.name)},body:file});if(!r.ok)throw new Error(await r.text()||'File upload failed');uploaded.push(await r.json())}return uploaded}
