 const count=toolbar.querySelector('#count');
 const button=document.createElement('button');
 button.type='button';button.id='clearFilters';button.className='clearFilters';button.textContent='Clear filters';button.setAttribute('aria-label','Clear all filters');
 toolbar.insertBefore(button,count);
