const NAVIGATION_HISTORY_JS=String.raw`
/* Browser-native navigation: each meaningful screen is addressable, refresh-safe,
   and participates in Back/Forward history. */
let routeHydrated=false;
let routeApplying=false;
const routeParams=()=>{
 const params=new URLSearchParams(location.hash.replace(/^#/,''));
 return {view:params.get('view')||'dashboard',scope:params.get('scope')||'year',list:params.get('list')||'',status:params.get('status')||'',event:params.get('event')||'',comments:params.get('comments')||''};
};
const routeSnapshot=()=>{
 const eventOpen=$('#backdrop')?.style.display==='flex'&&current?.id?current.id:'';
 const commentsOpen=$('#commentBackdrop')?.style.display==='flex'&&commentEvent?.id?commentEvent.id:'';
 return {view:view||'dashboard',scope:dashboardScope||'year',list:view==='semester'?reportListHeading:'',status:view==='semester'?reportStatusFilter:'',event:eventOpen,comments:commentsOpen};
};
const routeHash=state=>{
 const params=new URLSearchParams();
 if(state.view&&state.view!=='dashboard')params.set('view',state.view);
 if(state.scope&&state.scope!=='year')params.set('scope',state.scope);
 if(state.list)params.set('list',state.list);
 if(state.status)params.set('status',state.status);
 if(state.event)params.set('event',state.event);
 if(state.comments)params.set('comments',state.comments);
 const value=params.toString();return value?'#'+value:location.pathname+location.search;
};
const sameRoute=(a,b)=>a.view===b.view&&a.scope===b.scope&&(a.list||'')===(b.list||'')&&(a.status||'')===(b.status||'')&&a.event===b.event&&a.comments===b.comments;
function writeRoute(mode='push'){
 if(routeApplying||!routeHydrated)return;
 const next=routeSnapshot(),previous=history.state?.nsbeRoute||routeParams();
 if(sameRoute(next,previous))return;
 history[mode+'State']({...(history.state||{}),nsbeRoute:next},'',routeHash(next));
 document.title=(next.event||next.comments?((events.find(e=>e.id===(next.event||next.comments))?.title||'Event')+' | '):'')+'UMKC NSBE Monthly Activity Report';
}
function applyRoute(state,replace=false){
 routeApplying=true;
 const valid=/^(dashboard|all|semester|weekly|review|undated|2026-(08|09|10|11|12)|2027-(01|02|03|04|05))$/;
 view=valid.test(state.view||'')?state.view:'dashboard';
 dashboardScope=['year','fall','spring'].includes(state.scope)?state.scope:'year';
 reportListHeading=view==='semester'?(state.list||'Total Reports'):'';
 reportStatusFilter=view==='semester'?(state.status||''):'';
 $('#backdrop').style.display='none';
 if($('#commentBackdrop'))$('#commentBackdrop').style.display='none';
 render();
 if(state.event&&events.some(e=>e.id===state.event))openForm(state.event);
 else if(state.comments&&events.some(e=>e.id===state.comments))openCommentForm(state.comments);
 const normalized=routeSnapshot();
 if(replace||!sameRoute(normalized,state))history.replaceState({...(history.state||{}),nsbeRoute:normalized},'',routeHash(normalized));
 document.title=(normalized.event||normalized.comments?((events.find(e=>e.id===(normalized.event||normalized.comments))?.title||'Event')+' | '):'')+'UMKC NSBE Monthly Activity Report';
 routeApplying=false;
 document.documentElement.classList.add('routeReady');
 const loader=document.querySelector('.routeLoader');if(loader)setTimeout(()=>loader.remove(),180);
}
const renderBeforeRouting=render;
render=function(){
 if(!routeHydrated&&events.length){routeHydrated=true;applyRoute(history.state?.nsbeRoute||routeParams(),true);return}
 renderBeforeRouting();
};
window.addEventListener('popstate',event=>{if(events.length)applyRoute(event.state?.nsbeRoute||routeParams())});
document.addEventListener('click',event=>{
 const target=event.target.closest('button,a');if(!target)return;
 const meaningful=target.matches('[data-view],[data-toggle],[data-scope],[data-status],[data-lane],[data-total-reports],[data-executive-comments],[data-comment-event],.open,.close,.commentClose');
 if(meaningful)setTimeout(()=>writeRoute('push'),0);
},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape')setTimeout(()=>writeRoute('push'),0)},true);
`;
