async function init(db){await db.prepare("CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at TEXT NOT NULL, updated_by TEXT NOT NULL)").run();const x=await db.prepare("SELECT COUNT(*) count FROM events").first();if(!Number(x?.count||0)){const now=new Date().toISOString();await db.batch(seed().map(e=>{e.semester=sourceSemester(e);e.sourceIssue=SOURCE_ISSUES[e.id]||"";return db.prepare("INSERT INTO events (id,data,updated_at,updated_by) VALUES (?,?,?,?)").bind(e.id,JSON.stringify(e),now,"System")}));return}const rows=await db.prepare("SELECT id,data FROM events").all();let updates=[];for(const row of rows.results){let event=JSON.parse(row.data),changed=false,semester=sourceSemester(event),issue=SOURCE_ISSUES[event.id]||"";if(event.semester!==semester){event.semester=semester;changed=true}if(event.sourceIssue!==issue){event.sourceIssue=issue;changed=true}if(event.id==="NSBE-026"&&event.date!=="2026-11-17"){event.date="2026-11-17";changed=true}if(changed)updates.push(db.prepare("UPDATE events SET data=?,updated_at=?,updated_by=? WHERE id=?").bind(JSON.stringify(event),new Date().toISOString(),"Source PDF reconciliation",event.id))}if(updates.length)await db.batch(updates)}
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{"content-type":"application/json","cache-control":"no-store"}});
function sameValue(left,right){return JSON.stringify(left??null)===JSON.stringify(right??null)}
function listOf(value){return Array.isArray(value)?value.filter(Boolean):value&&typeof value==="object"?[value]:[]}
function itemKey(item){return item?.id||item?.key||JSON.stringify(item)}
function mergeSharedList(currentValue,baseValue,incomingValue){const current=listOf(currentValue),base=listOf(baseValue),incoming=listOf(incomingValue),result=new Map(current.map(item=>[itemKey(item),item])),baseMap=new Map(base.map(item=>[itemKey(item),item])),incomingKeys=new Set(incoming.map(itemKey));for(const item of base)if(!incomingKeys.has(itemKey(item)))result.delete(itemKey(item));for(const item of incoming){const key=itemKey(item),original=baseMap.get(key);if(!original||!sameValue(original,item))result.set(key,item)}return [...result.values()]}
function mergeEventRecord(current,base,incoming){if(!base)return incoming;const merged={...current};for(const [key,value] of Object.entries(incoming)){if(["id","updatedAt","updatedBy"].includes(key)||sameValue(value,base[key]))continue;if(["pictures","attendanceFile","executiveComments"].includes(key))merged[key]=mergeSharedList(current[key],base[key],value);else merged[key]=value}return merged}
async function api(req,env){await init(env.DB);if(req.method==="GET"){const q=await env.DB.prepare("SELECT data,updated_at,updated_by FROM events ORDER BY id").all();return json({events:q.results.map(r=>({...JSON.parse(r.data),updatedAt:r.updated_at,updatedBy:r.updated_by}))});}if(req.method==="PATCH"){const {event,base}=await req.json();if(!event?.id)return json({error:"Missing event"},400);const who=req.headers.get("oai-authenticated-user-email")||"Shared-link user";for(let attempt=0;attempt<5;attempt++){const row=await env.DB.prepare("SELECT data,updated_at FROM events WHERE id=?").bind(event.id).first();if(!row)return json({error:"Event not found"},404);const merged=mergeEventRecord(JSON.parse(row.data),base,event),now=new Date().toISOString(),result=await env.DB.prepare("UPDATE events SET data=?,updated_at=?,updated_by=? WHERE id=? AND updated_at=?").bind(JSON.stringify(merged),now,who,event.id,row.updated_at).run();if(Number(result.meta?.changes||0)>0)return json({event:{...merged,updatedAt:now,updatedBy:who}})}return json({error:"Another person updated this event at the same moment. Your changes were protected; please save once more."},409);}return json({error:"Method not allowed"},405);}
async function files(req,env,url){if(req.method==="PUT"){let match=url.pathname.match(/^\/api\/files\/([^/]+)\/(pictures|attendanceFile|comment-[a-zA-Z0-9_-]+)$/);if(!match)return new Response("Invalid upload path",{status:400});let length=Number(req.headers.get("content-length")||0);if(length>20*1024*1024)return new Response("Each file must be 20 MB or smaller.",{status:413});let eventId=decodeURIComponent(match[1]).replace(/[^a-zA-Z0-9_-]/g,"_"),kind=match[2],raw=req.headers.get("x-file-name")||"upload",name;try{name=decodeURIComponent(raw)}catch{name=raw}name=name.replace(/[\r\n]/g," ").slice(0,180);let body=await req.arrayBuffer();if(body.byteLength>20*1024*1024)return new Response("Each file must be 20 MB or smaller.",{status:413});let key=`evidence/${eventId}/${kind}/${Date.now()}-${name.replace(/[^a-zA-Z0-9._-]/g,"_")}`;let type=req.headers.get("content-type")||"application/octet-stream";await env.BUCKET.put(key,body,{httpMetadata:{contentType:type}});return json({name,type,size:body.byteLength,key,url:"/api/files?key="+encodeURIComponent(key)});}if(req.method==="GET"||req.method==="DELETE"){let key=url.searchParams.get("key");if(!key||!key.startsWith("evidence/"))return new Response("Invalid file",{status:400});if(req.method==="DELETE"){await env.BUCKET.delete(key);return json({deleted:true});}let object=await env.BUCKET.get(key);if(!object)return new Response("File not found",{status:404});let name=key.split("/").pop().replace(/^\d+-/,"");return new Response(object.body,{headers:{"content-type":object.httpMetadata?.contentType||"application/octet-stream","content-disposition":`inline; filename="${name.replace(/["\\]/g,"_")}"`,"cache-control":"private, max-age=60"}});}return new Response("Method not allowed",{status:405});}
